import { GraphQLError } from 'graphql';
import { ModeInput } from './modeInput';
import { OrderDirection } from './orderDirection';
export type GraphQLHook<Input, Response = any> = () => [
    GraphQLRequestFunction<Input, Response>
];
export type GraphQLRequestFunction<Input, Response> = (variables: GraphQLVariables<Input>) => GraphQLResponse<Response>;
export type GraphQLVariables<Input> = {
    variables: {
        input: Input & {
            mode: ModeInput;
        };
    };
};
export type GraphQLResponse<Data = any> = Promise<{
    errors?: GraphQLError[];
    data: {
        [key: string]: {
            edges: {
                node: Data;
            }[];
        };
    };
}>;
export type GraphQLQueryOptions = {
    filter: object;
    mode: ModeInput;
    sortOrder: {
        orderBy: string;
        orderDirection: OrderDirection;
    };
};
